import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        a = []
        for _ in range(n - 1):
            a.append(int(next(iterator)))

        b = []
        for _ in range(n - 1):
            b.append(int(next(iterator)))

        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        low = 1
        high = 10**18

        def check(power):
            visited = [False] * (n + 1)
            current_power = power
            visited[1] = True

            queue = [1]
            last_from = [-1] * (n + 1)
            order = []

            while queue:
                node = queue.pop(0)
                order.append(node)

                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        if last_from[node] != neighbor:
                            visited[neighbor] = True
                            last_from[neighbor] = node
                            queue.append(neighbor)
                            break

                if len(queue) == 0:
                    break

            if sum(visited) < n:
                return False

            current_power = power
            count = 0

            for node in order:
                if node == 1:
                    continue
                if not visited[node]:
                    continue
                idx = node - 2
                if current_power > a[idx]:
                    current_power += b[idx]
                    count += 1
                else:
                    return False

            return count == n - 1

        def can_complete(start_power):
            visited = [False] * (n + 1) # 1-indexed
            visited[1] = True
            current_power = start_power
            count_beaten = 0

            if n == 1:
                return True

            frontier = [(1, -1)]

            while count_beaten < n - 1:
                found_next = False
                new_frontier = []

                for u, prev_u in frontier:
                    for v in adj[u]:
                        if not visited[v]:
                            if v != prev_u:
                                visited[v] = True
                                idx = v - 2
                                if current_power > a[idx]:
                                    current_power += b[idx]
                                    count_beaten += 1
                                new_frontier.append((v, u))
                                found_next = True
                                break
                    if found_next:
                        break

                if not found_next:
                    return False

                frontier = new_frontier

            return True

        ans = high
        l, r = 1, 10**18

        while l <= r:
            mid = (l + r) // 2
            if can_complete(mid):
                ans = mid
                r = mid - 1
            else:
                l = mid + 1

        results.append(str(ans))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
